{
  "items": [
    {
      "title": "German Bundestag Open Data – Parliamentary Documents, Members and Voting Records",
      "url_or_doi": "https://www.bundestag.de/services/opendata/",
      "justification": "Official open-data portal of the German Bundestag providing machine-readable parliamentary documents, plenary proceedings, member biographies and roll-call voting records. Includes data from the 2020s, particularly the 20th legislative period (2021–2025) and subsequent parliamentary activities. Useful for studying parliamentary behavior, political representation, legislative processes, government accountability and political party dynamics."
    },
    {
      "title": "German Federal Election 2025 – Official Open Data",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2025/ergebnisse/opendata.html",
      "justification": "Official dataset published by Germany's Federal Returning Officer containing results of the 2025 federal parliamentary election. Provides downloadable CSV and XML data covering political parties, candidates, constituencies and electoral results. Particularly valuable for analyzing Germany's electoral system, political competition, voter preferences and changes in parliamentary representation during the 2020s."
    },
    {
      "title": "German Federal Election 2021 – Official Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2021/ergebnisse.html",
      "justification": "Official results of Germany's 2021 federal election, including constituency-level outcomes, party vote shares and electoral participation. Provides an essential baseline for studying the transition from Angela Merkel's government to the subsequent coalition government. Can be compared with the 2025 election results to investigate political realignment, party competition and electoral change."
    },
    {
      "title": "German Election Database (GERDA) – Historical and Contemporary Election Results",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Research-oriented collection of German election datasets covering different geographic levels and electoral periods, including elections during the 2020s. Provides downloadable data in formats such as CSV, Excel and RDS. Particularly useful for longitudinal analysis of political party support, geographic voting patterns, constituency changes and electoral behavior across Germany."
    },
    {
      "title": "German Bundestag – Political Party Financial Reports (Rechenschaftsberichte)",
      "url_or_doi": "https://www.bundestag.de/parlament/praesidium/parteienfinanzierung/rechenschaftsberichte",
      "justification": "Official collection of financial accountability reports submitted by German political parties. Includes reports for financial years 2020–2024, documenting party revenues, expenditures, assets, donations and public financing. Relevant for studying political organizations, party financing, financial transparency and the relationship between public funding and political competition. The underlying information is primarily published in parliamentary documents rather than as a standardized machine-readable dataset."
    },
    {
      "title": "Party Donations Watch – German Political Party Donations",
      "url_or_doi": "https://parteispendenwatch.de/",
      "justification": "Publicly accessible platform tracking financial donations to German political parties using official Bundestag disclosures. Provides information on donors, recipient parties and donation amounts, with regularly updated records. Useful for investigating political financing, financial influence, transparency and relationships between political organizations and private donors during the 2020s."
    },
    {
      "title": "DonationWatch – Political Party Donations in Germany",
      "url_or_doi": "https://donation.watch/en/germany",
      "justification": "Dataset-oriented platform presenting disclosed large donations to German political parties. Includes historical records extending into the 2020s and information about contributing individuals or organizations, donation amounts and recipient parties. Particularly relevant for studying political finance, donor networks, organizational influence and transparency in German democratic institutions. Coverage is limited to donations exceeding applicable disclosure thresholds."
    },
    {
      "title": "Object-Centric and Traditional Event Data of the German Bundestag",
      "url_or_doi": "https://zenodo.org/records/16811928",
      "justification": "Academic research dataset published on Zenodo containing structured parliamentary process data extracted from the German Bundestag's information systems. Covers legislative periods up to the 20th Bundestag (2021–2025). Includes information about parliamentary activities, legislative procedures and interactions involving parliamentarians and government members. Especially suitable for computational political science, institutional analysis, process mining and research on parliamentary decision-making."
    },
    {
      "title": "Every Bundestag Vote Dataset – German Parliamentary Voting",
      "url_or_doi": "https://fis.uni-bamberg.de/entities/researchdata/15589a0c-ef09-477f-b996-622af5a0293e",
      "justification": "Academic dataset documenting plenary votes in the German Bundestag during the 19th legislative period (2017–2021), including the beginning of the 2020s. Covers recorded and non-recorded votes and supports analysis of parliamentary voting procedures, opposition strategies and legislative decision-making. Particularly useful for comparing voting behavior before and after the 2021 change of government."
    },
    {
      "title": "Politblick – German Bundestag Voting Data",
      "url_or_doi": "https://politblick.de/daten/",
      "justification": "Data download portal providing structured information about parliamentary voting in Germany, including historical voting records from completed legislative periods. Useful for examining voting patterns, political party alignment, parliamentary coalitions and differences between government and opposition behavior during the 2020s."
    },
    {
      "title": "Konrad Adenauer Foundation – German Election Results Since 1946",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Historical election data collection covering German federal elections, European Parliament elections and elections in Germany's federal states. Includes election results from the 2020s and supports comparisons across different levels of government. Particularly relevant for studying Germany's federal political system, regional political organizations, electoral trends and long-term changes in party competition."
    },
    {
      "title": "German Bundestag – Political Party Financial Reports and Public Financing",
      "url_or_doi": "https://www.bundestag.de/parlament/praesidium/parteienfinanzierung/die_staatliche_parteienfinanzierung/07_rechenschaftsberichte-249386",
      "justification": "Official Bundestag resource explaining and providing access to political party financial reporting. Relevant reports contain information about the financial resources, expenditures and assets of political parties, including reporting periods in the 2020s. Useful for examining the organizational structure and financial sustainability of political parties, as well as transparency and accountability within Germany's political system."
    },
    {
      "title": "German Bundestag – Political Party Financial Data for 2024",
      "url_or_doi": "https://www.bundestag.de/presse/hib/kurzmeldungen-1148998",
      "justification": "Official publication presenting financial data for seven political parties represented in the Bundestag at the end of 2024. Contains information on party revenues, expenditures and financial balances. Provides a focused source for comparing major German political organizations during the 2020s and investigating differences in their financial resources. The landing page references the underlying official financial reports."
    },
    {
      "title": "German Bundestag – Political Party Financial Data for 2023",
      "url_or_doi": "https://www.bundestag.de/presse/hib/kurzmeldungen-1050024",
      "justification": "Official Bundestag publication covering financial reports for parties represented in parliament during 2023, including CDU, SPD, Bündnis 90/Die Grünen, AfD, FDP, CSU, Die Linke and SSW. Provides data on financial income, expenditure and party resources. Useful for analyzing the financial characteristics of German political organizations during the 2021–2025 legislative period."
    },
    {
      "title": "German Bundestag – Political Party Financial Data for 2022",
      "url_or_doi": "https://www.bundestag.de/presse/hib/kurzmeldungen-1010468",
      "justification": "Official Bundestag publication linking to financial reports from 28 political parties for the 2022 reporting year. Particularly useful for studying smaller political organizations outside the major parliamentary parties, comparing organizational resources and investigating the diversity of Germany's party system during the 2020s."
    }
  ]
}
